// 1. Get the output from the AI Agent node
const aiOutput = $input.first().json.output || $input.first().json.text; 

// 2. Helper to clean Markdown wrappers
function cleanMarkdown(text) {
    if (!text) return "";
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
    return jsonMatch ? jsonMatch[1] : text;
}

let jsonString = cleanMarkdown(aiOutput);
let finalData = {};

try {
    // STRATEGY A: Try standard parsing first (Best Case)
    finalData = JSON.parse(jsonString);

} catch (e) {
    // STRATEGY B: Landmark Extraction (The "Nuclear Option")
    // This ignores broken syntax (like unescaped quotes inside values)
    // and simply slices text between known keys.

    const extractField = (fullText, startKey, endKey) => {
        // 1. Find start key
        const startIdx = fullText.indexOf(`"${startKey}"`);
        if (startIdx === -1) return null;

        // 2. Find colon
        const colonIdx = fullText.indexOf(":", startIdx);
        if (colonIdx === -1) return null;

        // 3. Find start of NEXT key (or end of object)
        let endIdx;
        if (endKey) {
            endIdx = fullText.indexOf(`"${endKey}"`, colonIdx);
        } else {
            endIdx = fullText.lastIndexOf("}");
        }

        if (endIdx === -1) return null;

        // 4. Extract raw chunk
        let rawValue = fullText.substring(colonIdx + 1, endIdx).trim();

        // 5. Cleanup: Remove trailing comma
        if (rawValue.endsWith(',')) {
            rawValue = rawValue.slice(0, -1).trim();
        }

        // 6. Cleanup: Remove surrounding quotes 
        if (rawValue.startsWith('"') && rawValue.endsWith('"')) {
            rawValue = rawValue.slice(1, -1);
        }

        // 7. Cleanup: Try to unescape standard characters
        try {
            rawValue = JSON.parse(`"${rawValue.replace(/"/g, '\\"')}"`);
        } catch (err) {
            rawValue = rawValue.replace(/\\"/g, '"').replace(/\\n/g, '\n');
        }

        return rawValue;
    };

    // Apply extraction in the specific order:
    finalData = {
        date: extractField(jsonString, "date", "simple_title"),

        simple_title: extractField(jsonString, "simple_title", "full_title"),

        full_title: extractField(jsonString, "full_title", "URL"),

        URL: extractField(jsonString, "URL", "picture_cover_prompts"),

        picture_cover_prompts: extractField(jsonString, "picture_cover_prompts", "picture_content_prompts"),

        picture_content_prompts: extractField(jsonString, "picture_content_prompts", "reason"),

        // The last field goes until the end of the JSON object
        reason: extractField(jsonString, "reason", null),

        _status: "parsed_with_landmark_fallback"
    };
}

// 3. Return the object containing ALL fields
return finalData;
